SourceCode.Declaration:
[DataContract]
class TFMDrawFlowLogicBlockConnectionContract
{
    str node;
    str output;
    str input;
}

Method.Source:
[DataMember('node')]
public str parmNode(str _node = node)
{
    node = _node;
    return node;
}

[DataMember('output')]
public str parmOutput(str _output = output)
{
    output = _output;
    return output;
}

[DataMember('input')]
public str parmInput(str _input = input)
{
    input = _input;
    return input;
}

public static TFMDrawFlowLogicBlockConnectionContract Construct(str _node, str _output, str _input)
{
    TFMDrawFlowLogicBlockConnectionContract contract = new TFMDrawFlowLogicBlockConnectionContract();
    contract.parmNode(_node);
    contract.parmOutput(_output);
    contract.parmInput(_input);

    return contract;
}
